-- Idempotent PostgreSQL script for Receipt Reprint Audit Logs and Sales History Indexes
BEGIN;
SET LOCAL lock_timeout = '10s';

DO $$
BEGIN
    IF current_database() <> 'pos_db' THEN
        RAISE EXCEPTION 'ReceiptReprintLogs.sql must run against pos_db';
    END IF;
END $$;

-- 1. ReceiptReprintLogs Table for tracking controlled invoice reprints
CREATE TABLE IF NOT EXISTS "ReceiptReprintLogs" (
    "ReprintLogId" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "OrderId" BIGINT NOT NULL,
    "InvoiceNumber" VARCHAR(50) NULL,
    "BranchId" INT NOT NULL,
    "OutletId" INT NOT NULL,
    "CashierId" VARCHAR(450) NOT NULL,
    "ReprintReason" VARCHAR(255) NOT NULL DEFAULT 'CUSTOMER_REQUEST',
    "ReprintedAt" TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "PrinterName" VARCHAR(100) NULL,
    "PrintStatus" VARCHAR(30) NOT NULL DEFAULT 'SUCCESS',
    "ErrorMessage" TEXT NULL,
    CONSTRAINT "FK_ReceiptReprintLogs_Orders" FOREIGN KEY ("OrderId") REFERENCES "Orders" ("OrderId") ON DELETE CASCADE
);

-- 2. Performance Indexes for Sales History & Search
CREATE INDEX IF NOT EXISTS "IX_Orders_BranchId_CreatedAt" ON "Orders" ("BranchId", "CreatedAt");
CREATE INDEX IF NOT EXISTS "IX_Orders_OutletId_CreatedAt" ON "Orders" ("OutletId", "CreatedAt");
CREATE INDEX IF NOT EXISTS "IX_Orders_InvoiceNumber" ON "Orders" ("InvoiceNumber");
CREATE INDEX IF NOT EXISTS "IX_Orders_OrderNumber" ON "Orders" ("OrderNumber");
CREATE INDEX IF NOT EXISTS "IX_Orders_CashierId" ON "Orders" ("CashierId");
CREATE INDEX IF NOT EXISTS "IX_ReceiptReprintLogs_OrderId" ON "ReceiptReprintLogs" ("OrderId");

COMMIT;
